WITH kept_keys AS (SELECT customer_id FROM sessions EXCEPT ALL SELECT customer_id FROM sessions WHERE started_at >= '2023-04-12'), verified AS (SELECT s.* FROM sessions s JOIN kept_keys k ON s.customer_id = k.customer_id) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, SIZE(COLLECT_SET(country)) AS num_countries, COUNT(*) FILTER (WHERE browser = 'Edge') AS edge_rows, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, COUNT_IF(country = 'JP') AS jp_events FROM verified GROUP BY 1 HAVING span_minutes > 0 ORDER BY edge_rows DESC
